        call    addChar
; ---- addChar( hexDigit[ ( w >> 8 ) & 15 ] )
        mov     ax, [addHex__w]
        mov     cl, 8                       ; 8086 has no shift-by-immediate
        shr     ax, cl                      ; unsigned >>
        and     ax, 15
        mov     bx, ax
        mov     al, [hexDigit + bx]
        mov     [addChar__c], al            ; u8 -> u8, no widening
        call    addChar
; ---- addChar( hexDigit[ ( w >> 4 ) & 15 ] )
        mov     ax, [addHex__w]
        mov     cl, 4                       ; 8086 has no shift-by-immediate
        shr     ax, cl                      ; unsigned >>
        and     ax, 15
        mov     bx, ax
        mov     al, [hexDigit + bx]
        mov     [addChar__c], al            ; u8 -> u8, no widening
        call    addChar
; ---- addChar( hexDigit[ w & 15 ] )
        mov     ax, [addHex__w]
        and     ax, 15
        mov     bx, ax
        mov     al, [hexDigit + bx]
        mov     [addChar__c], al            ; u8 -> u8, no widening
        call    addChar
        ret

; ============================================== sub addLineEnd ====

addLineEnd:
; ---- addChar( 13 )
        mov     byte [addChar__c], 13
        call    addChar
; ---- addChar( 10 )
        mov     byte [addChar__c], 10
        call    addChar
        ret

; ============================================== sub putHex ====

putHex:
; ---- putChar( hexDigit[ ( w >> 12 ) & 15 ] )
        mov     ax, [putHex__w]
        mov     cl, 12                      ; 8086 has no shift-by-immediate
        shr     ax, cl                      ; unsigned >>
        and     ax, 15
        mov     bx, ax
        mov     al, [hexDigit + bx]
        mov     [putChar__c], al            ; u8 -> u8, no widening
        call    putChar
; ---- putChar( hexDigit[ ( w >> 8 ) & 15 ] )
        mov     ax, [putHex__w]
        mov     cl, 8                       ; 8086 has no shift-by-immediate
        shr     ax, cl                      ; unsigned >>
        and     ax, 15
        mov     bx, ax
        mov     al, [hexDigit + bx]
        mov     [putChar__c], al            ; u8 -> u8, no widening
        call    putChar
; ---- putChar( hexDigit[ ( w >> 4 ) & 15 ] )
        mov     ax, [putHex__w]
        mov     cl, 4                       ; 8086 has no shift-by-immediate
        shr     ax, cl                      ; unsigned >>
        and     ax, 15
        mov     bx, ax
        mov     al, [hexDigit + bx]
        mov     [putChar__c], al            ; u8 -> u8, no widening
        call    putChar
; ---- putChar( hexDigit[ w & 15 ] )
        mov     ax, [putHex__w]
        and     ax, 15
        mov     bx, ax
        mov     al, [hexDigit + bx]
        mov     [putChar__c], al            ; u8 -> u8, no widening
        call    putChar
        ret

; ============================================== u16 readKeyEx ====

readKeyEx:
; ---- _ah = 0x10
        mov     byte [_ah], 16
; ---- int 0x16
        call    int16
; ---- return _ax
        mov     ax, [_ax]
        mov     [readKeyEx__ret], ax
        ret

; ============================================== u16 shiftFlags ====

shiftFlags:
; ---- _ah = 0x12
        mov     byte [_ah], 18
; ---- int 0x16
        call    int16
; ---- return _ax
        mov     ax, [_ax]
        mov     [shiftFlags__ret], ax
        ret

; ============================================== u16 countStrings ====

countStrings:
; ---- n = 0
        mov     word [countStrings__n], 0
; ---- for ( u16 i = 0; i < bytes; i++ ) {
        mov     word [countStrings__i], 0
.L106:
        mov     ax, [countStrings__i]
        mov     bx, [countStrings__bytes]
        cmp     ax, bx
        jae     .L108                       ; unsigned <
; ---- if ( peek8( at + i ) == strTerm ) n++
        mov     ax, [countStrings__at]
        mov     bx, [countStrings__i]
        add     ax, bx
        mov     bx, ax
        mov     al, [bx]                    ; peek8 - unchecked, by design
        cmp     al, 36                      ; byte operands, no widening
        jne     .L110                       ; unsigned ==
        inc     word [countStrings__n]
.L110:
.L107:
        inc     word [countStrings__i]
        jmp     .L106
.L108:
; ---- return n
        mov     ax, [countStrings__n]
        mov     [countStrings__ret], ax
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int16:
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x16
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pushf
        pop     ax
        and     al, 1                       ; carry is bit 0
        mov     [_cf], al
        ret

int21:
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pushf
        pop     ax
        and     al, 1                       ; carry is bit 0
        mov     [_cf], al
        ret

; ============================================================ data ====

; ---- reserved globals: the machine registers ----
_ax:            dw      0
_al:            equ     _ax
_ah:            equ     _ax + 1
_bx:            dw      0
_bl:            equ     _bx
_bh:            equ     _bx + 1
_cx:            dw      0
_cl:            equ     _cx
_ch:            equ     _cx + 1
_dx:            dw      0
_dl:            equ     _dx
_dh:            equ     _dx + 1
_si:            dw      0
_di:            dw      0
_cf:            db      0

